"Fica na área de transferência do telemóvel: dá para colar nas Mensagens. Para o levar para fora do jogo, o endereço fica selecionado: Ctrl+C.": "電話のクリップボードにコピーされているので、メッセージに貼り付けられます。ゲームの外へ持ち出すには、アドレスが選択された状態になっているので、Ctrl+Cを押してください。",
