"Cada separador guarda o seu histórico, mas só o que está à frente é que corre: ao voltar a um separador a página recarrega. É isso que evita ter páginas a consumir som, vídeo e rede dentro do jogo.": "各タブはそれぞれ履歴を保持しますが、動作するのは最前面のものだけです。タブに戻るとページが再読み込みされます。これにより、ゲーム内でページが音声、動画、ネットワークを消費するのを防いでいます。",
